/// The icon at a size, in the current foreground style.
struct SubjectIcon: View {
    let name: String
    var size: CGFloat = 17

    var body: some View {
        let s = SubjectIcons.shape(name)
        ZStack {
            Glyph(path: s.stroke, box: CGRect(x: 0, y: 0, width: 24, height: 24))
                .stroke(style: StrokeStyle(lineWidth: 1.6 * size / 24, lineCap: .round, lineJoin: .round))
            Glyph(path: s.fill, box: CGRect(x: 0, y: 0, width: 24, height: 24))
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}
